// Generated by Upskale Studio. Do not edit this file directly.
//
// The storefront every page reads: where the customer is, the stores that
// serve them, the chosen store's menu, the options picked for a product, the
// cart, checkout, their orders and their account. A port of
// package:upskale_storefront's Storefront (the Flutter apps'), so the website
// and the apps behave alike. Server reads go through TanStack Query, so a
// menu or an order asked for twice is fetched once.
import type { QueryClient } from "@tanstack/react-query";
import { rememberStore } from "./visitor";

export type Json = Record<string, any>;

export class ApiError extends Error {
  constructor(
    public status: number,
    public error: string,
    message: string,
    public fields?: Record<string, string>,
  ) {
    super(message);
    this.name = "ApiError";
  }
}

export function errorText(failure: unknown): string {
  return failure instanceof ApiError ? failure.message : "Something went wrong. Try again.";
}

const TOKEN_KEY = "upskale.session";
const CART_KEY = "upskale.cart";
const STORE_KEY = "upskale.store";

function stored(key: string): string | null {
  try {
    return localStorage.getItem(key);
  } catch {
    return null;
  }
}

function store(key: string, value: string | null) {
  try {
    if (value == null) localStorage.removeItem(key);
    else localStorage.setItem(key, value);
  } catch {
    // Kept for this visit only.
  }
}

const cents = (value: unknown) => (typeof value === "number" && Number.isFinite(value) ? Math.round(value) : 0);
const textOf = (value: unknown) => (value == null ? "" : String(value));

// ------------------------------------------------------------------- the API

/** The tenant API, from the browser: CORS is open on it, and nothing here is secret. */
export class StorefrontApi {
  token: string | null = stored(TOKEN_KEY);
  constructor(public baseUrl: string) {}

  async request<T = any>(
    method: string,
    path: string,
    options: { body?: unknown; auth?: boolean; query?: Record<string, unknown> } = {},
  ): Promise<T> {
    const headers: Record<string, string> = { Accept: "application/json" };
    if (options.body !== undefined) headers["Content-Type"] = "application/json";
    if (options.auth && this.token) headers.Authorization = "Bearer " + this.token;
    const search = new URLSearchParams();
    for (const [key, value] of Object.entries(options.query ?? {})) {
      if (value == null || value === "") continue;
      if (Array.isArray(value)) value.forEach((item) => search.append(key, String(item)));
      else search.set(key, String(value));
    }
    const query = search.toString();
    let response: Response;
    try {
      response = await fetch(this.baseUrl.replace(/\/+$/, "") + "/api/v1" + path + (query ? "?" + query : ""), {
        method,
        headers,
        body: options.body === undefined ? undefined : JSON.stringify(options.body),
      });
    } catch {
      throw new ApiError(0, "offline", "Could not reach the store. Check your connection.");
    }
    if (response.status === 204) return undefined as T;
    const text = await response.text();
    let parsed: any = null;
    try {
      parsed = text ? JSON.parse(text) : null;
    } catch {
      throw new ApiError(response.status, "invalid_response", "The store sent an answer this site can't read.");
    }
    if (!response.ok) {
      throw new ApiError(
        response.status,
        parsed?.error ?? "unknown",
        parsed?.message ?? "Something went wrong.",
        parsed?.fields,
      );
    }
    return parsed as T;
  }

  segment(value: string) {
    return encodeURIComponent(value);
  }
}

// ----------------------------------------------------------------- options

export interface OptionChoice {
  id: string;
  label: string;
  priceCents: number;
  groups: OptionGroup[];
}

export interface OptionGroup {
  id: string;
  label: string;
  min: number;
  max: number;
  choices: OptionChoice[];
}

const isRequired = (group: OptionGroup) => group.min > 0;
const isSingle = (group: OptionGroup) => group.max === 1;

/** A product's groups from the tenant API's addon_groups (or the preview's shape). */
export function parseGroups(groups: unknown, depth = 0): OptionGroup[] {
  if (!Array.isArray(groups) || depth > 6) return [];
  const number = (value: unknown) => (typeof value === "number" ? Math.round(value) : 0);
  return groups
    .slice(0, 20)
    .filter((group): group is Json => !!group && typeof group === "object" && group.is_active !== false)
    .map((group) => ({
      id: textOf(group.id),
      label: textOf(group.label ?? group.name),
      min: "min" in group ? number(group.min) : Math.max(number(group.min_select), group.is_required === true ? 1 : 0),
      max: Math.max(1, number("max" in group ? group.max : group.max_select)),
      choices: ((group.choices ?? group.options ?? []) as unknown[])
        .slice(0, 40)
        .filter((choice): choice is Json => !!choice && typeof choice === "object" && (choice as Json).is_available !== false)
        .map((choice) => ({
          id: textOf(choice.id),
          label: textOf(choice.label ?? choice.name),
          priceCents: number(choice.price ?? choice.price_delta_cents),
          groups: parseGroups(
            choice.groups ?? (choice.child_group && typeof choice.child_group === "object" ? [choice.child_group] : null),
            depth + 1,
          ),
        })),
    }));
}

export const groupsOf = (product: unknown) =>
  parseGroups(product && typeof product === "object" ? (product as Json).addon_groups : null);

function findGroup(groups: OptionGroup[], id: string): OptionGroup | null {
  for (const group of groups) {
    if (group.id === id) return group;
    for (const choice of group.choices) {
      const nested = findGroup(choice.groups, id);
      if (nested) return nested;
    }
  }
  return null;
}

/** The groups as a page reads them (optionGroups): selected groups' own groups right after, a level deeper. */
function groupBindings(groups: OptionGroup[], selected: Record<string, string[]>, depth = 0): Json[] {
  const out: Json[] = [];
  for (const group of groups) {
    const ids = selected[group.id] ?? [];
    out.push({
      id: group.id,
      label: group.label,
      min: group.min,
      max: group.max,
      single: isSingle(group),
      required: isRequired(group),
      depth,
      selected_count: ids.length,
      choices: group.choices.map((choice) => ({
        id: choice.id,
        label: choice.label,
        price_cents: choice.priceCents,
        selected: ids.includes(choice.id),
        disabled: !ids.includes(choice.id) && !isSingle(group) && ids.length >= group.max,
      })),
    });
    for (const choice of group.choices) if (ids.includes(choice.id)) out.push(...groupBindings(choice.groups, selected, depth + 1));
  }
  return out;
}

interface Selection {
  valid: boolean;
  labels: string[];
  priceCents: number;
  selections: Json[];
}

function selectionOf(groups: OptionGroup[], selected: Record<string, string[]>): Selection {
  let valid = true,
    price = 0;
  const labels: string[] = [],
    selections: Json[] = [];
  for (const group of groups) {
    const ids = selected[group.id] ?? [];
    if (
      ids.length < group.min ||
      ids.length > group.max ||
      new Set(ids).size !== ids.length ||
      ids.some((id) => !group.choices.some((choice) => choice.id === id))
    )
      valid = false;
    for (const choice of group.choices.filter((choice) => ids.includes(choice.id))) {
      const nested = selectionOf(choice.groups, selected);
      valid = valid && nested.valid;
      price += choice.priceCents + nested.priceCents;
      labels.push(choice.label, ...nested.labels);
      selections.push({ addon_id: choice.id, quantity: 1, children: nested.selections });
    }
  }
  return { valid, labels, priceCents: price, selections };
}

