// ---------------------------------------------------------------- checkout

const FULFILMENTS = ["delivery", "pickup"];
const PAYMENT_METHODS = ["online", "cash", "card", "mobile_money", "wallet"];

export class Checkout {
  fulfilment = "delivery";
  paymentMethod: string | null = null;
  tipCents = 0;
  notes: string | null = null;
  customerName = "";
  customerPhone = "";
  customerEmail: string | null = null;
  addressId: string | null = null;
  addressLine1: string | null = null;
  addressLine2: string | null = null;
  city: string | null = null;
  region: string | null = null;
  postalCode: string | null = null;
  latitude: number | null = null;
  longitude: number | null = null;
  deliveryInstructions: string | null = null;
  deliveryPresetId: string | null = null;
  pointConfirmed = false;

  get delivery() {
    return this.fulfilment === "delivery";
  }

  update(changes: Json) {
    const text = (value: unknown) => {
      const string = value == null ? "" : String(value).trim();
      return string === "" ? null : string;
    };
    const number = (value: unknown) => (typeof value === "number" ? value : null);
    for (const [key, value] of Object.entries(changes)) {
      switch (key) {
        case "fulfilment":
        case "fulfilment_type": {
          const next = value === "collection" ? "pickup" : String(value);
          if (FULFILMENTS.includes(next)) this.fulfilment = next;
          break;
        }
        case "payment_method": {
          const next = text(value);
          this.paymentMethod = next && PAYMENT_METHODS.includes(next) ? next : null;
          break;
        }
        case "tip_cents":
          this.tipCents = typeof value === "number" ? Math.min(100000000, Math.max(0, Math.round(value))) : 0;
          break;
        case "notes":
          this.notes = text(value);
          break;
        case "customer_name":
          this.customerName = text(value) ?? "";
          break;
        case "customer_phone":
          this.customerPhone = text(value) ?? "";
          break;
        case "customer_email":
          this.customerEmail = text(value);
          break;
        case "delivery_address_id":
          this.addressId = text(value);
          break;
        case "delivery_address_line1":
          this.addressLine1 = text(value);
          break;
        case "delivery_address_line2":
          this.addressLine2 = text(value);
          break;
        case "delivery_city":
          this.city = text(value);
          break;
        case "delivery_region":
          this.region = text(value);
          break;
        case "delivery_postal_code":
          this.postalCode = text(value);
          break;
        case "delivery_latitude":
          this.latitude = number(value);
          break;
        case "delivery_longitude":
          this.longitude = number(value);
          break;
        case "delivery_instructions":
          this.deliveryInstructions = text(value);
          break;
        case "delivery_preset_id":
          this.deliveryPresetId = text(value);
          break;
      }
    }
  }

  useLocation(location: Location | null) {
    if (!location) return;
    this.latitude ??= location.latitude;
    this.longitude ??= location.longitude;
    this.addressLine1 ??= location.label;
  }

  quoteBody(storeId: string, items: Json[]): Json {
    const body: Json = { store_id: storeId, fulfilment_type: this.fulfilment, tip_cents: this.tipCents, items };
    if (this.paymentMethod) body.payment_method = this.paymentMethod;
    if (this.delivery) {
      if (this.latitude != null && this.longitude != null) {
        body.delivery_latitude = this.latitude;
        body.delivery_longitude = this.longitude;
      }
      if (this.deliveryPresetId) body.delivery_preset_id = this.deliveryPresetId;
    }
    return body;
  }

  orderBody(storeId: string, items: Json[]): Json {
    const body: Json = {
      ...this.quoteBody(storeId, items),
      customer_name: this.customerName,
      customer_phone: this.customerPhone,
    };
    if (this.customerEmail) body.customer_email = this.customerEmail;
    if (this.notes) body.notes = this.notes;
    if (this.delivery) {
      if (this.addressId) body.delivery_address_id = this.addressId;
      else {
        if (this.addressLine1) body.delivery_address_line1 = this.addressLine1;
        if (this.addressLine2) body.delivery_address_line2 = this.addressLine2;
        if (this.city) body.delivery_city = this.city;
        if (this.region) body.delivery_region = this.region;
        if (this.postalCode) body.delivery_postal_code = this.postalCode;
      }
      if (this.deliveryInstructions) body.delivery_instructions = this.deliveryInstructions;
    }
    return body;
  }

  toJson(): Json {
    return {
      fulfilment: this.fulfilment,
      payment_method: this.paymentMethod,
      tip_cents: this.tipCents,
      notes: this.notes,
      customer_name: this.customerName,
      customer_phone: this.customerPhone,
      customer_email: this.customerEmail,
      delivery_address_id: this.addressId,
      delivery_address_line1: this.addressLine1,
      delivery_address_line2: this.addressLine2,
      delivery_instructions: this.deliveryInstructions,
      delivery_preset_id: this.deliveryPresetId,
      delivery_latitude: this.latitude,
      delivery_longitude: this.longitude,
      delivery_point_confirmed: this.pointConfirmed,
    };
  }

  resetForNextOrder() {
    this.tipCents = 0;
    this.notes = null;
    this.deliveryInstructions = null;
  }
}

// -------------------------------------------------------------- storefront

export interface Location {
  label: string;
  latitude: number;
  longitude: number;
}

export type Status = "idle" | "loading" | "ready" | "error";
export type AddResult = "added" | "unavailable" | "needsOptions";

export class Storefront {
  readonly api: StorefrontApi | null;
  readonly pinnedStoreId: string | null;
  /** Whether choosing a store loads its menu (and cuisines), or leaves that to the pages. */
  loadsMenu = true;
  private listeners = new Set<() => void>();
  /** Bumped on every change: what React re-renders by. */
  version = 0;

  location: Location | null = null;
  places: Json[] = [];
  cities: Json[] = [];
  locating = false;
  locationError: string | null = null;
  stores: Json[] = [];
  storesStatus: Status = "idle";
  store: Json | null = null;
  menu: Json | null = null;
  cuisines: Json | null = null;
  deliveryOptions: Json | null = null;

  lines: CartLine[] = [];
  cartStoreId: string | null = null;
  private nextLine = 0;
  checkout = new Checkout();
  quote: Json | null = null;
  fieldErrors: Record<string, string> = {};

  orders: Json[] = [];
  order: Json | null = null;
  review: Json | null = null;
  driverLocation: Location | null = null;
  addresses: Json[] = [];
  user: Json | null = null;
  signingIn = false;
  authError: string | null = null;

  /** The product a page has open, as OpenProduct carried it. */
  openProduct: Json | null = null;
  private optionsProductId: unknown = undefined;
  private optionSelections: Record<string, string[]> = {};

  private requests = { stores: 0, menu: 0, places: 0, quote: 0 };
  private following: AbortController | null = null;
  private guestStarting: Promise<string> | null = null;

  constructor(
    apiBaseUrl: string,
    pinnedStoreId: string,
    private queries: QueryClient,
  ) {
    this.api = apiBaseUrl ? new StorefrontApi(apiBaseUrl) : null;
    this.pinnedStoreId = pinnedStoreId || null;
  }

  get connected() {
    return this.api != null;
  }

  // --- change ---------------------------------------------------------------

  subscribe = (listener: () => void) => {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  };

  getVersion = () => this.version;

  notify() {
    this.version++;
    this.saveCart();
    for (const listener of this.listeners) listener();
  }

  private get _api() {
    if (!this.api) throw new Error("This site isn't connected to a store.");
    return this.api;
  }

  // --- session --------------------------------------------------------------

  get signedIn() {
    return !!this.api?.token && this.user?.is_anonymous === false;
  }

  /** A session token, starting a guest session if needed. */
  async ensure(): Promise<string> {
    const api = this._api;
    if (api.token) return api.token;
    this.guestStarting ??= api
      .request("POST", "/auth/guest")
      .then((session) => {
        this.setSession(session);
        return session.token as string;
      })
      .finally(() => (this.guestStarting = null));
    return this.guestStarting;
  }

  private setSession(session: Json | null) {
    const api = this._api;
    api.token = session?.token ?? null;
    this.user = session?.user ?? null;
    store(TOKEN_KEY, api.token);
    this.notify();
  }

  /** Picks up the session kept from before, and who it's for. */
  async restore() {
    const api = this.api;
    if (!api?.token || this.user) return;
    try {
      this.user = await api.request("GET", "/me", { auth: true });
      this.notify();
    } catch (failure) {
      if (failure instanceof ApiError && failure.status === 401) this.setSession(null);
    }
  }

  async authenticate(signUp: boolean, email: string, password: string, name: string) {
    if (this.signingIn) return;
    if (!email.includes("@")) return this.setAuth(false, "Enter your email address.");
    if (!password) return this.setAuth(false, "Enter your password.");
    if (signUp && password.length < 8) return this.setAuth(false, "Choose a password of 8 characters or more.");
    this.setAuth(true, null);
    try {
      const session = signUp
        ? await this._api.request("POST", "/auth/sign-up", {
            auth: true,
            body: { email, password, ...(name ? { display_name: name } : {}) },
          })
        : await this._api.request("POST", "/auth/sign-in", { body: { email, password } });
      this.setSession(session);
      this.setAuth(false, null);
      void this.loadOrders();
    } catch (failure) {
      this.setAuth(false, errorText(failure));
    }
  }

  private setAuth(working: boolean, error: string | null) {
    this.signingIn = working;
    this.authError = error;
    this.notify();
  }

  signOut() {
    this.setSession(null);
    this.orders = [];
    this.addresses = [];
    this.notify();
  }

  // --- location -------------------------------------------------------------

  async searchPlaces(input: string) {
    const request = ++this.requests.places;
    if (input.trim().length < 3) {
      this.places = [];
      return this.notify();
    }
    await this.ensure();
    const body = await this._api.request("GET", "/places/autocomplete", {
      auth: true,
      query: { input: input.trim(), latitude: this.location?.latitude, longitude: this.location?.longitude },
    });
    if (request !== this.requests.places) return;
    this.places = (Array.isArray(body?.data) ? body.data : []).map((place: Json) => ({
      ...place,
      label: place.secondary_text ? `${place.main_text}, ${place.secondary_text}` : place.main_text,
    }));
    this.notify();
  }

  async resolvePlace(placeId: string): Promise<Location> {
    await this.ensure();
    const body = await this._api.request("GET", "/places/details", { auth: true, query: { place_id: placeId } });
    if (typeof body?.latitude !== "number" || typeof body?.longitude !== "number")
      throw new ApiError(0, "invalid", "This address has no coordinates.");
    return { label: body.address || body.name || "", latitude: body.latitude, longitude: body.longitude };
  }

  setLocation(location: Location | null) {
    this.location = location;
    this.notify();
  }

  async loadCities() {
    try {
      const body = await this.queries.fetchQuery({
        queryKey: ["cities"],
        queryFn: () => this._api.request("GET", "/cities"),
        staleTime: 5 * 60_000,
      });
      this.cities = (Array.isArray(body?.data) ? body.data : []).map((city: Json) => ({ ...city, label: city.name }));
      this.notify();
    } catch {
      // No cities is the same as none to offer.
    }
  }

  chooseCity(city: Json) {
    this.setLocation({ label: textOf(city.name), latitude: Number(city.latitude) || 0, longitude: Number(city.longitude) || 0 });
  }

  /** The browser's location, named when the address can be looked up. */
  async locateDevice() {
    this.locating = true;
    this.locationError = null;
    this.notify();
    try {
      const position = await new Promise<GeolocationPosition>((resolve, reject) => {
        if (!("geolocation" in navigator)) return reject(new Error("unsupported"));
        navigator.geolocation.getCurrentPosition(resolve, reject, { enableHighAccuracy: true, timeout: 12_000 });
      });
      let point: Location = { label: "Your location", latitude: position.coords.latitude, longitude: position.coords.longitude };
      try {
        await this.ensure();
        const named = await this._api.request("GET", "/places/reverse", {
          auth: true,
          query: { latitude: point.latitude, longitude: point.longitude },
        });
        if (named?.label) point = { ...point, label: named.label };
      } catch {
        // Unnamed is still a place to find stores near.
      }
      this.setLocation(point);
      return point;
    } catch (failure) {
      const code = (failure as GeolocationPositionError)?.code;
      this.locationError =
        code === 1
          ? "Location access is off for this site. Search for your address instead."
          : code === 3
            ? "Finding your location took too long. Search for your address instead."
            : "This browser can't share its location. Search for your address instead.";
      throw failure;
    } finally {
      this.locating = false;
      this.notify();
    }
  }

  // --- stores ---------------------------------------------------------------

  async searchStores(query?: string) {
    const request = ++this.requests.stores;
    this.storesStatus = "loading";
    this.notify();
    try {
      const params = {
        q: query?.trim() || undefined,
        latitude: this.location?.latitude,
        longitude: this.location?.longitude,
        status: "active",
        limit: 30,
      };
      const page = await this.queries.fetchQuery({
        queryKey: ["stores", params],
        queryFn: () => this._api.request("GET", "/stores", { query: params }),
        staleTime: 60_000,
      });
      if (request === this.requests.stores) {
        this.stores = Array.isArray(page?.data) ? page.data : [];
        this.storesStatus = "ready";
      }
    } catch (failure) {
      if (request === this.requests.stores) {
        this.storesStatus = "error";
      }
      throw failure;
    } finally {
      if (request === this.requests.stores) this.notify();
    }
  }

  /** Opens a store: its menu (required), cuisines and delivery options (optional). */
  async selectStore(idOrSlug: string, card?: Json) {
    const current = this.store;
    if (!current || (current.id !== idOrSlug && current.slug !== idOrSlug)) {
      // Another store's menu can't show meanwhile; the tapped card stands in.
      this.menu = null;
      this.cuisines = null;
      this.deliveryOptions = null;
      this.store = card ?? null;
    }
    const request = ++this.requests.menu;
    this.notify();
    if (!this.loadsMenu) return this.selectStoreOnly(idOrSlug, request);
    try {
      const api = this._api;
      const menu = await this.queries.fetchQuery({
        queryKey: ["menu", idOrSlug],
        queryFn: () => api.request("GET", `/stores/${api.segment(idOrSlug)}/menu`),
        staleTime: 60_000,
      });
      if (!menu || !Array.isArray(menu.categories)) throw new ApiError(0, "invalid", "The menu response is invalid.");
      const optional = <T>(read: () => Promise<T>) =>
        Promise.race([read(), new Promise<null>((resolve) => setTimeout(() => resolve(null), 4000))]).catch(() => null);
      const [cuisines, deliveryOptions] = await Promise.all([
        optional(() =>
          this.queries.fetchQuery({ queryKey: ["cuisines"], queryFn: () => api.request("GET", "/cuisines"), staleTime: 300_000 }),
        ),
        optional(() => this.deliveryOptionsOf(textOf(menu.store.id))),
      ]);
      if (request !== this.requests.menu) return;
      this.menu = menu;
      this.store = menu.store;
      void this.loadCart(textOf(menu.store.id));
      this.cuisines = cuisines as Json | null;
      this.deliveryOptions = deliveryOptions as Json | null;
      if (!this.pinnedStoreId) {
        store(STORE_KEY, textOf(menu.store.id));
        rememberStore(textOf(menu.store.id));
      }
    } finally {
      if (request === this.requests.menu) this.notify();
    }
  }

  /** A store's delivery options, asked for once a minute however many pages want them. */
  private deliveryOptionsOf(storeId: string) {
    const api = this._api;
    return this.queries.fetchQuery({
      queryKey: ["delivery-options", storeId],
      queryFn: () => api.request("GET", `/stores/${api.segment(storeId)}/delivery-options`),
      staleTime: 60_000,
    });
  }

  /** A store without its menu (the pages fetch that): the store and its delivery options. */
  private async selectStoreOnly(idOrSlug: string, request: number) {
    try {
      const api = this._api;
      const chosen = await this.queries.fetchQuery({
        queryKey: ["store", idOrSlug],
        queryFn: () => api.request("GET", `/stores/${api.segment(idOrSlug)}`),
        staleTime: 60_000,
      });
      if (!chosen?.id) throw new ApiError(0, "invalid", "The store response is invalid.");
      const deliveryOptions = await Promise.race([
        this.deliveryOptionsOf(textOf(chosen.id)),
        new Promise<null>((resolve) => setTimeout(() => resolve(null), 4000)),
      ]).catch(() => null);
      if (request !== this.requests.menu) return;
      this.store = chosen;
      this.deliveryOptions = deliveryOptions as Json | null;
      void this.loadCart(textOf(chosen.id));
      if (!this.pinnedStoreId) {
        store(STORE_KEY, textOf(chosen.id));
        rememberStore(textOf(chosen.id));
      }
    } finally {
      if (request === this.requests.menu) this.notify();
    }
  }

  /** The store a returning visitor last ordered from. */
  get savedStoreId() {
    return stored(STORE_KEY);
  }

  get products(): Json[] {
    const menu = this.menu;
    if (!menu) return [];
    const all: Json[] = [
      ...(menu.categories as Json[]).flatMap((category) => (Array.isArray(category.products) ? category.products : [])),
      ...(Array.isArray(menu.uncategorised) ? menu.uncategorised : []),
    ];
    return all.filter((product) => product.is_available_online !== false);
  }

  // --- product options -------------------------------------------------------

  selectionsFor(product: unknown): Record<string, string[]> {
    return product && typeof product === "object" && (product as Json).id === this.optionsProductId ? this.optionSelections : {};
  }

  private choose(product: unknown, groupId: string, choiceIds: string[]) {
    const id = product && typeof product === "object" ? (product as Json).id : undefined;
    if (id !== this.optionsProductId) {
      this.optionSelections = {};
      this.optionsProductId = id;
    }
    this.optionSelections = { ...this.optionSelections, [groupId]: choiceIds };
    this.notify();
  }

  toggleOption(product: unknown, groupId: string, choiceId: string) {
    const group = findGroup(groupsOf(product), groupId);
    const choice = group?.choices.find((item) => item.id === choiceId);
    if (!group || !choice) return;
    const ids = this.selectionsFor(product)[group.id] ?? [];
    if (isSingle(group)) return this.choose(product, group.id, [choice.id]);
    if (ids.includes(choice.id)) return this.choose(product, group.id, ids.filter((id) => id !== choice.id));
    if (ids.length < group.max) this.choose(product, group.id, [...ids, choice.id]);
  }

  configuration(product: unknown) {
    return selectionOf(groupsOf(product), this.selectionsFor(product));
  }

  // --- cart -------------------------------------------------------------------
  //
  // **On the server, when the site has one** (the tenant API's
  // /stores/{store}/cart): the customer's session's cart at each store,
  // priced there, so a reload, another tab or another device shows the same
  // cart. Each change shows at once here, then the server's answer (its
  // prices, its line ids) replaces it. A site with no API keeps the cart in
  // this browser, as before.

  /** Something the server refused (a cart problem): the runtime shows it. */
  onProblem: (message: string) => void = () => {};

  /** False once the tenant API turned out to have no cart (not updated yet). */
  private cartOnServer = true;

  private get serverCart() {
    return this.connected && this.cartOnServer;
  }

  /** A tenant API without /cart (older than 0083): the cart stays in this browser. */
  private noServerCart(failure: unknown) {
    if (!(failure instanceof ApiError) || (failure.status !== 404 && failure.status !== 405) || failure.error === "not_found") return false;
    this.cartOnServer = false;
    this.saveCart();
    return true;
  }

  /** The server's cart, as the lines the pages read. */
  private applyCart(cart: Json | null) {
    if (!cart || !Array.isArray(cart.items)) return;
    this.cartStoreId = textOf(cart.store_id) || this.cartStoreId;
    if (typeof cart.currency === "string" && /^[A-Z]{3}$/.test(cart.currency)) this.savedCurrency = cart.currency;
    this.lines = (cart.items as Json[]).map((item) => ({
      id: textOf(item.id),
      product: { id: item.product_id, name: item.name, image_url: item.image_url },
      quantity: Number(item.quantity) || 1,
      unitCents: cents(item.unit_cents),
      choices: Array.isArray(item.choices) ? item.choices : [],
      selections: Array.isArray(item.selections) ? item.selections : [],
      notes: item.notes ?? null,
      problem: item.problem ?? null,
    }));
    this.notify();
  }

  private cartRequests = 0;

  /** A cart change sent to the server; its answer is the cart from then on. */
  private async sendCart(method: string, path: string, body?: Json) {
    const storeId = this.storeForCart;
    if (!this.serverCart || !storeId) return;
    const request = ++this.cartRequests;
    try {
      await this.ensure();
      const cart = await this._api.request(method, `/stores/${this._api.segment(storeId)}/cart${path}`, { auth: true, body });
      if (request === this.cartRequests) this.applyCart(cart);
    } catch (failure) {
      if (this.noServerCart(failure)) return;
      this.onProblem(failure instanceof Error ? failure.message : "The cart couldn't be updated.");
      // What the server has, whatever happened here.
      void this.loadCart(storeId);
    }
  }

  /** A store's cart from the server: the session's, once there is one. */
  /** The cart being asked for, so a second ask for the same store waits on it. */
  private cartLoading: { storeId: string; done: Promise<void> } | null = null;

  async loadCart(storeId: string) {
    if (!this.serverCart || !storeId || !this.api?.token) return;
    if (this.cartLoading?.storeId === storeId) return this.cartLoading.done;
    const done = this.fetchCart(storeId).finally(() => {
      if (this.cartLoading?.done === done) this.cartLoading = null;
    });
    this.cartLoading = { storeId, done };
    return done;
  }

  private async fetchCart(storeId: string) {
    if (this.cartStoreId && this.cartStoreId !== storeId) this.lines = [];
    this.cartStoreId = storeId;
    const request = ++this.cartRequests;
    try {
      const cart = await this._api.request("GET", `/stores/${this._api.segment(storeId)}/cart`, { auth: true });
      if (request === this.cartRequests) this.applyCart(cart);
    } catch (failure) {
      // The cart shows as it was; the next change asks again.
      this.noServerCart(failure);
    }
  }

  private addLine(product: Json, quantity: number, unitCents: number, choices: string[] = [], selections: Json[] = []) {
    const storeId = (this.store?.id as string | undefined) ?? (product.store_id as string | undefined) ?? null;
    if (storeId && this.cartStoreId && storeId !== this.cartStoreId) this.lines = [];
    this.cartStoreId = storeId ?? this.cartStoreId;
    // On the server too: its answer replaces this line.
    void this.sendCart("POST", "/items", {
      product_id: textOf(product.id),
      quantity: Math.min(99, Math.max(1, quantity)),
      selections,
    });
    this.lines = [
      ...this.lines,
      {
        id: "line-" + ++this.nextLine,
        product,
        quantity: Math.min(99, Math.max(1, quantity)),
        unitCents,
        choices,
        selections,
        notes: null,
      },
    ];
    this.notify();
  }

  /** One product, whole (its addon_groups too): a list's products may come without them. */
  async product(id: string): Promise<Json> {
    const answer = await this.queries.fetchQuery({
      queryKey: ["product", id],
      queryFn: () => this._api.request("GET", "/products/" + encodeURIComponent(id)),
      staleTime: 60_000,
    });
    return answer && typeof answer === "object" && answer.data && typeof answer.data === "object" && !Array.isArray(answer.data) ? answer.data : answer;
  }

  add(product: Json, quantity = 1): AddResult {
    if (product.is_available === false) return "unavailable";
    if (groupsOf(product).some(isRequired)) return "needsOptions";
    this.addLine(product, quantity, cents(product.display_price_cents));
    return "added";
  }

  addConfigured(product: Json, quantity = 1): AddResult {
    if (product.is_available === false) return "unavailable";
    const selection = this.configuration(product);
    if (!selection.valid) return "needsOptions";
    this.addLine(product, quantity, cents(product.display_price_cents) + selection.priceCents, selection.labels, selection.selections);
    return "added";
  }

  changeLine(id: string, delta: number) {
    const line = this.lines.find((item) => item.id === id);
    if (!line) return;
    const quantity = Math.min(99, line.quantity + delta);
    // A line still on its way to the server (line-…) is settled by its answer.
    if (!id.startsWith("line-"))
      void (quantity > 0
        ? this.sendCart("PATCH", "/items/" + encodeURIComponent(id), { quantity })
        : this.sendCart("DELETE", "/items/" + encodeURIComponent(id)));
    this.lines = this.lines
      .map((item) => (item.id === id ? { ...item, quantity } : item))
      .filter((item) => item.quantity > 0);
    this.notify();
  }

  removeLine(id: string) {
    if (!id.startsWith("line-")) void this.sendCart("DELETE", "/items/" + encodeURIComponent(id));
    this.lines = this.lines.filter((line) => line.id !== id);
    this.notify();
  }

  get cartCount() {
    return this.lines.reduce((sum, line) => sum + (line.problem ? 0 : line.quantity), 0);
  }

  get cartTotal() {
    return this.lines.reduce((sum, line) => sum + (line.problem ? 0 : line.unitCents * line.quantity), 0);
  }

  private orderItems() {
    // What can't be ordered now (a problem the server named) isn't sent.
    return this.lines.filter((line) => !line.problem).map((line) => ({
      product_id: textOf(line.product.id),
      quantity: line.quantity,
      selections: line.selections,
      ...(line.notes?.trim() ? { notes: line.notes.trim() } : {}),
    }));
  }

  private saveCart() {
    // Not before the saved cart is read back: an empty one would replace it.
    if (!this.cartRestored) return;
    // The server's cart is the cart: only which store's it is stays here.
    if (this.serverCart) {
      store(CART_KEY, JSON.stringify({ storeId: this.cartStoreId, lines: [], currency: this.currency }));
      return;
    }
    store(CART_KEY, JSON.stringify({ storeId: this.cartStoreId, lines: this.lines, next: this.nextLine, currency: this.currency }));
  }

  /** The currency of the store the cart is from, remembered with the cart. */
  private savedCurrency: string | null = null;

  /**
   * What prices are in: the open store's, the quote's, the cart's store's
   * (remembered from before), a listed store's; ZAR when nothing says.
   */
  get currency(): string {
    const named = (value: unknown) => (typeof value === "string" && /^[A-Z]{3}$/.test(value) ? value : null);
    return (
      named(this.store?.currency) ??
      named(this.quote?.currency) ??
      this.savedCurrency ??
      named(this.stores.find((item) => named(item?.currency))?.currency) ??
      "ZAR"
    );
  }

  private cartRestored = false;

  /**
   * The cart from an earlier visit, read once the page has hydrated (so the
   * first render matches the server's). The server re-prices every line.
   */
  restoreCart() {
    if (this.cartRestored) return;
    this.cartRestored = true;
    try {
      const saved = JSON.parse(stored(CART_KEY) ?? "null");
      if (this.serverCart) {
        // Which store's cart: the one saved, else the chosen store's.
        if (typeof saved?.currency === "string" && /^[A-Z]{3}$/.test(saved.currency)) this.savedCurrency = saved.currency;
        const storeId = (typeof saved?.storeId === "string" && saved.storeId) || this.pinnedStoreId || this.savedStoreId;
        if (storeId) void this.loadCart(storeId);
      } else if (saved && Array.isArray(saved.lines)) {
        this.lines = saved.lines;
        this.cartStoreId = saved.storeId ?? null;
        this.nextLine = Number(saved.next) || saved.lines.length;
        if (typeof saved.currency === "string" && /^[A-Z]{3}$/.test(saved.currency)) this.savedCurrency = saved.currency;
      }
    } catch {
      // A cart that can't be read is an empty one.
    }
    this.notify();
  }

  // --- checkout ---------------------------------------------------------------

  private get storeForCart() {
    return this.cartStoreId ?? (this.store?.id as string | undefined) ?? null;
  }

  /** The cart and choices the last quote was asked for. */
  private quotedFor = "";

  /**
   * The quote kept current while a page shows the checkout: asked for again
   * whenever the cart or a checkout choice changes, so the charges a store
   * adds (and its delivery fee) show before the order is placed, never after.
   */
  keepQuote() {
    const storeId = this.storeForCart;
    if (!this.connected || !storeId || this.lines.length === 0) return;
    if (this.checkout.delivery) this.checkout.useLocation(this.location);
    const key = JSON.stringify(this.checkout.quoteBody(storeId, this.orderItems()));
    if (key !== this.quotedFor) void this.refreshQuote();
  }

  async refreshQuote() {
    const storeId = this.storeForCart;
    if (!storeId || this.lines.length === 0) {
      this.quote = null;
      return this.notify();
    }
    const request = ++this.requests.quote;
    if (this.checkout.delivery) this.checkout.useLocation(this.location);
    // What this quote is for (keepQuote asks again only when it changes).
    this.quotedFor = JSON.stringify(this.checkout.quoteBody(storeId, this.orderItems()));
    this.notify();
    try {
      await this.ensure();
      const quote = await this._api.request("POST", "/orders/quote", {
        auth: true,
        body: this.checkout.quoteBody(storeId, this.orderItems()),
      });
      if (request === this.requests.quote) {
        this.quote = quote;
      }
    } catch {
      // The checkout keeps the last quote; placing the order prices it anyway.
    } finally {
      if (request === this.requests.quote) this.notify();
    }
  }

  async placeOrder(): Promise<Json> {
    const storeId = this.storeForCart;
    if (!storeId || this.lines.length === 0) throw new Error("There is nothing in the cart to order.");
    this.fieldErrors = {};
    this.notify();
    try {
      await this.ensure();
      if (this.checkout.delivery) this.checkout.useLocation(this.location);
      const placed = await this._api.request("POST", "/orders", {
        auth: true,
        body: this.checkout.orderBody(storeId, this.orderItems()),
      });
      this.lines = [];
      this.checkout.resetForNextOrder();
      this.quote = null;
      this.order = placed;
      this.review = null;
      this.orders = [placed, ...this.orders.filter((item) => item.id !== placed.id)];
      void this.followOrder(placed.id);
      return placed;
    } catch (failure) {
      if (failure instanceof ApiError) this.fieldErrors = failure.fields ?? {};
      throw failure;
    } finally {
      this.notify();
    }
  }

  get deliveryFeeCents() {
    const presetId = this.checkout.deliveryPresetId;
    if (presetId) {
      const preset = ((this.deliveryOptions?.presets as Json[]) ?? []).find((item) => String(item.id) === presetId);
      if (preset) return cents(preset.fee_cents);
    }
    if (this.quote && this.checkout.delivery) return cents(this.quote.delivery_fee_cents);
    return cents(this.store?.delivery_fee_cents);
  }

  get deliveryProblem(): string | null {
    if (!this.checkout.delivery) return null;
    if (this.deliveryOptions?.mode === "preset")
      return this.checkout.deliveryPresetId ? null : "Choose where we should deliver.";
    return this.checkout.pointConfirmed ? null : "Confirm your delivery location on the map.";
  }

  confirmDeliveryPoint(latitude: number, longitude: number) {
    this.checkout.latitude = latitude;
    this.checkout.longitude = longitude;
    this.checkout.pointConfirmed = true;
    this.checkout.fulfilment = "delivery";
    this.notify();
  }

  // --- orders -----------------------------------------------------------------

  async loadOrders() {
    if (!this.connected) return;
    this.notify();
    try {
      await this.ensure();
      const page = await this._api.request("GET", "/orders", { auth: true });
      this.orders = Array.isArray(page?.data) ? page.data : [];
    } catch {
      // No orders to show is the same as none yet.
    } finally {
      this.notify();
    }
  }

  async openOrder(idOrNumber: string) {
    await this.ensure();
    const api = this._api;
    const next = await api.request("GET", `/orders/${api.segment(idOrNumber)}`, { auth: true });
    if (this.order?.id !== next.id) {
      this.review = null;
      this.driverLocation = null;
    }
    this.order = next;
    if (next.status === "delivered") {
      try {
        this.review = await api.request("GET", `/orders/${api.segment(next.id)}/review`, { auth: true });
      } catch {
        this.review = null;
      }
    }
    this.notify();
    if (!["delivered", "cancelled", "failed"].includes(next.status)) void this.followOrder(next.id);
    return next;
  }

  /** Follows an order live (server-sent events, read as a stream for the bearer token). */
  async followOrder(orderId: string) {
    this.following?.abort();
    const controller = new AbortController();
    this.following = controller;
    if (!this.connected) return;
    try {
      const token = await this.ensure();
      const api = this._api;
      const response = await fetch(api.baseUrl.replace(/\/+$/, "") + `/api/v1/orders/${api.segment(orderId)}/events`, {
        headers: { Accept: "text/event-stream", Authorization: "Bearer " + token },
        signal: controller.signal,
      });
      if (!response.ok || !response.body) return;
      const reader = response.body.pipeThrough(new TextDecoderStream()).getReader();
      let buffer = "";
      for (;;) {
        const { value, done } = await reader.read();
        if (done) break;
        buffer += value;
        let end: number;
        while ((end = buffer.indexOf("\n\n")) >= 0) {
          const block = buffer.slice(0, end);
          buffer = buffer.slice(end + 2);
          let type = "message",
            data = "";
          for (const line of block.split("\n")) {
            if (line.startsWith("event:")) type = line.slice(6).trim();
            else if (line.startsWith("data:")) data += line.slice(5).trim();
          }
          try {
            this.onOrderEvent(orderId, type, data ? JSON.parse(data) : {});
          } catch {
            // One unreadable event isn't the end of the stream.
          }
        }
      }
    } catch {
      // Live updates stop; the order is still there to reopen.
    }
  }

  private onOrderEvent(orderId: string, type: string, event: Json) {
    if (type === "status" && event.status) {
      if (this.order?.id === orderId) this.order = { ...this.order, status: event.status };
      this.orders = this.orders.map((item) => (item.id === orderId ? { ...item, status: event.status } : item));
      if (event.status === "delivered" || event.status === "cancelled") this.driverLocation = null;
    } else if (type === "driver_location" && this.order?.id === orderId && typeof event.latitude === "number") {
      this.driverLocation = { label: textOf(this.order?.driver_name) || "Driver", latitude: event.latitude, longitude: event.longitude };
    }
    this.notify();
  }

  awaitingPayment(order: Json | null = this.order) {
    return !!order && order.payment_method === "online" && order.payment_status !== "paid" &&
      order.status !== "cancelled" && order.status !== "failed";
  }

  /** Where to pay for an online order: the business's provider, in this tab. */
  async payOnline(orderId: string) {
    await this.ensure();
    const api = this._api;
    const body = await api.request("POST", `/orders/${api.segment(orderId)}/payfast`, { auth: true });
    if (typeof body?.url !== "string") throw new ApiError(0, "invalid", "The store didn't say where to pay.");
    window.location.assign(body.url);
  }

  async cancelOrder(orderId = this.order?.id as string | undefined) {
    if (!orderId) throw new Error("No order is open.");
    await this.ensure();
    const api = this._api;
    const cancelled = await api.request("POST", `/orders/${api.segment(orderId)}/cancel`, { auth: true });
    if (this.order?.id === orderId) this.order = cancelled;
    this.orders = this.orders.map((item) => (item.id === orderId ? cancelled : item));
    this.notify();
  }

  async submitReview(review: { foodRating?: number; deliveryRating?: number; foodComment?: string; deliveryComment?: string }) {
    const current = this.order;
    if (!current) throw new Error("No order is open.");
    const delivery = current.fulfilment_type === "delivery";
    await this.ensure();
    const api = this._api;
    const body: Json = {};
    if (review.foodRating) body.food_rating = review.foodRating;
    if (review.foodComment?.trim()) body.food_comment = review.foodComment.trim();
    if (delivery && review.deliveryRating) body.delivery_rating = review.deliveryRating;
    if (delivery && review.deliveryComment?.trim()) body.delivery_comment = review.deliveryComment.trim();
    this.review = await api.request("POST", `/orders/${api.segment(current.id)}/review`, { auth: true, body });
    this.notify();
  }

  // --- account ----------------------------------------------------------------

  async loadAddresses() {
    await this.ensure();
    const page = await this._api.request("GET", "/addresses", { auth: true });
    this.addresses = Array.isArray(page?.data) ? page.data : [];
    this.notify();
  }

  async saveAddress(body: Json) {
    await this.ensure();
    await this._api.request("POST", "/addresses", { auth: true, body });
    await this.loadAddresses();
  }

  async deleteAddress(id: string) {
    await this.ensure();
    const api = this._api;
    await api.request("DELETE", `/addresses/${api.segment(id)}`, { auth: true });
    if (this.checkout.addressId === id) this.checkout.update({ delivery_address_id: null });
    await this.loadAddresses();
  }

  async requestPasswordReset(email: string) {
    await this._api.request("POST", "/auth/password/forgot", { body: { email } });
  }

  // --- bindings ---------------------------------------------------------------

  /** What pages read, by the same names as the Studio preview and the apps. */
  bindings(product: unknown): Json {
    const selection = this.configuration(product);
    const categories = this.menu ? (this.menu.categories as Json[]) : null;
    const presets = (this.deliveryOptions?.presets as Json[] | undefined) ?? null;
    const out: Json = {
      places: this.places,
      cities: this.cities,
      locating: this.locating,
      locationError: this.locationError,
      storesLoading: this.storesStatus === "loading",
      optionGroups: groupBindings(groupsOf(product), this.selectionsFor(product)),
      deliveryFeeCents: this.deliveryFeeCents,
      cart: this.lines.map((line) => ({
        id: line.id,
        product: line.product,
        product_id: textOf(line.product.id),
        name: textOf(line.product.name),
        quantity: line.quantity,
        unit_cents: line.unitCents,
        line_total_cents: line.unitCents * line.quantity,
        choices: line.choices,
        notes: line.notes,
      })),
      cartCount: this.cartCount,
      cartTotal: this.cartTotal,
      configuration: { valid: selection.valid, addon_price_cents: selection.priceCents },
      checkout: this.checkout.toJson(),
      orders: this.orders,
      signedIn: this.signedIn,
      signingIn: this.signingIn,
      authError: this.authError,
    };
    if (this.location) out.location = this.location;
    if (this.stores.length) out.stores = this.stores;
    if (this.store) out.store = this.store;
    if (this.menu && categories) {
      out.menu = this.menu;
      out.categories = categories;
      out.category = categories[0] ?? null;
      out.products = this.products;
    }
    if (this.cuisines) {
      out.cuisinesPage = this.cuisines;
      out.cuisines = this.cuisines.data ?? [];
    }
    if (this.deliveryOptions) {
      out.deliveryOptions = this.deliveryOptions;
      out.deliveryPresets = presets;
      out.deliveryPreset = presets?.[0] ?? null;
    }
    if (this.quote) out.quote = this.quote;
    if (Object.keys(this.fieldErrors).length) out.checkoutErrors = this.fieldErrors;
    if (this.order) {
      out.order = this.order;
      out.orderItems = this.order.items ?? [];
    }
    if (this.review) out.review = this.review;
    if (this.driverLocation) out.driverLocation = this.driverLocation;
    if (this.addresses.length) out.addresses = this.addresses;
    if (this.user) out.me = this.user;
    return out;
  }
}
